        'attach_hint' => 'bug report પર સ્ક્રીનશોટ સામાન્ય રીતે જ રિપોર્ટ હોય છે. ઈમેલમાં એમ્બેડ કરેલી ઈમેજ — સહી, લોગો, ટ્રેકિંગ પિક્સેલ — ક્યારેય મોકલવામાં આવતી નથી, ફક્ત કોઈએ ઇરાદાપૂર્વક જોડેલી ફાઇલો જ મોકલાય છે. મોટી ફાઇલોને એસ્કેલેશન નિષ્ફળ કરવાને બદલે છોડી દેવામાં આવે છે, અને કંઈપણ મોકલાય તે પહેલાં તમે હંમેશા યાદી જુઓ છો.',
