        'tika_intro' => 'FreeITSMને એક ડોક્યુમેન્ટ-રીડિંગ સર્વિસ તરફ નિર્દેશ કરે છે. Word, Excel, PowerPoint અને પ્લેન ટેક્સ્ટ ફાઇલો આના વગર પણ પહેલેથી શોધાય છે; Tika એ ફોર્મેટ ઉમેરે છે જે FreeITSM પોતાની મેળે વાંચી શકતું નથી.',
        'tika_security_title' => 'તેને નેટવર્કથી દૂર રાખો',
