        'tika_image_note' => '-full ઇમેજનો ઉપયોગ કરો. નાનીમાં કેરેક્ટર રેકગ્નિશન નથી, તેથી સ્કેન કરેલા ડોક્યુમેન્ટ ખાલી પાછા આવશે.',
