        'slack_bot_token' => 'Bot user OAuth ટોકન',
        'slack_bot_token_hint' => 'તમારા Slack app માંથી, OAuth &amp; Permissions હેઠળ. xoxb- થી શરૂ થાય છે. app ઇન્સ્ટોલ કર્યા પછી તમને તે મળે છે, તેથી પહેલી વાર સાચવતી વખતે તેને ખાલી રાખો.',
        'slack_signing_secret' => 'Signing secret',
        'slack_signing_secret_hint' => 'તમારા Slack app માંથી, Basic Information હેઠળ. આ રીતે FreeITSM સાબિત કરે છે કે મેસેજ ખરેખર Slack તરફથી આવ્યો છે, તેથી જ્યાં સુધી તે સેટ ન થાય ત્યાં સુધી કંઈ સ્વીકારવામાં આવતું નથી.',
        'slack_watch_channel' => 'ફક્ત આ ચેનલ જુઓ',
        'slack_watch_channel_hint' => 'C08ABCDEF જેવો Slack ચેનલ ID. app ને આમંત્રિત કરેલી દરેક ચેનલમાંથી ટિકિટ ઉઠાવવા ખાલી રાખો — જે વ્યસ્ત ચેનલ પર દરેક મેસેજ દીઠ એક ટિકિટ બનાવે છે, તેથી મોટાભાગના લોકો અહીં એક હેલ્પ ચેનલનું નામ આપે છે.',
        'slack_company_shared' => 'શેર્ડ — સેન્ડર પ્રમાણે નક્કી કરો',
        'slack_company_hint' => 'આ workspace ને એક કંપની સાથે પિન કરો, અથવા તેને શેર્ડ રહેવા દો અને સેન્ડરને નક્કી કરવા દો.',
        'slack_delete_confirm' => 'Slack workspace “{name}” કાઢી નાખવું છે? તેમાંથી પહેલેથી ઉઠાવેલી ટિકિટોનો ઇતિહાસ જળવાઈ રહેશે; ફક્ત નવા મેસેજ આવવાનું બંધ થશે.',
        'slack_diag_title' => 'Slack હેલ્થ ચેક',
        'slack_diag_desc' => 'શાંતિથી ખોટું થઈ શકે તેવી દરેક વસ્તુ તપાસે છે — ફક્ત ટોકન કામ કરે છે કે નહીં તે જ નહીં. દરેક પરિણામ કહે છે કે તેના વિશે શું કરવું.',
        'slack_diag_running' => 'તપાસી રહ્યું છે — આ Slack સાથે અને તમારા પોતાના પબ્લિક સરનામા સાથે વાત કરે છે, તેથી થોડી સેકન્ડ આપો…',
        'slack_diag_rerun' => 'ફરી ચલાવો',
        'slack_diag_all_ok' => 'બધું બરાબર છે. જોવાયેલી Slack ચેનલમાં પોસ્ટ થયેલા મેસેજ ટિકિટ બનશે, અને જવાબ થ્રેડમાં પાછા જશે.',
        'slack_diag_some_warn' => 'કામ કરી રહ્યું છે, પણ જાણવા જેવું કંઈક છે. નીચેનું કંઈ પણ ટિકિટ આવવાનું અટકાવતું નથી, પણ વાંચવા જેવું છે.',
        'slack_diag_some_fail' => 'કંઈક ખોટું છે અને મેસેજ નહીં આવે. નીચે નિષ્ફળ ગયેલી તપાસ કહે છે કે શું કરવું.',
        'slack_app_title' => 'Slack app',
        'slack_copy_manifest' => 'manifest કૉપિ કરો',
        'slack_scopes_heading' => 'app ને શું કરવાની મંજૂરી છે',
        'slack_scopes_desc' => 'app ને મંજૂરી આપતી વખતે તમારા Slack એડમિનને આ યાદી દેખાશે. અહીં કંઈ પણ તેને ચેનલ બનાવવા, લોકોને આમંત્રિત કરવા કે જ્યાં આમંત્રિત ન કરાયું હોય ત્યાં પોસ્ટ કરવા દેતું નથી.',
        'slack_step1' => 'Slackમાં, <strong>api.slack.com/apps</strong> પર જાઓ અને <strong>Create New App → From a manifest</strong> પસંદ કરો. તમે સર્વિસ ડેસ્ક જ્યાં જોઈએ છે તે workspace પસંદ કરો.',
        'slack_step2' => 'આ manifest પેસ્ટ કરો. તે નામ, પરવાનગીઓ અને Slack જ્યાં મેસેજ મોકલે છે તે સરનામું સેટ કરે છે, તેથી હાથે ટિક કરવાનું કંઈ નથી.',
        'slack_step3' => '<strong>Install to Workspace</strong> પર ક્લિક કરો અને તેને મંજૂર કરો. પછી <strong>Bot User OAuth Token</strong> અને <strong>Signing Secret</strong> ને અહીંના Edit ફોર્મમાં પાછા કૉપિ કરો — Slack ટોકન ફરી બતાવશે નહીં. <strong>જો Slack પીળું &ldquo;Reinstall to Workspace&rdquo; બેનર બતાવે, તો પહેલાં તેના પર ક્લિક કરો</strong> — નહીંતર ટોકનમાં તેની મોટાભાગની પરવાનગીઓ ખૂટતી હશે અને ટિકિટ સેન્ડરના નામ વગર આવશે.',
        'slack_step4' => 'નીચેનું request URL Slack <strong>Event Subscriptions</strong> હેઠળ બતાવે છે તેની સાથે મેળ ખાય છે કે નહીં તપાસો. તમે app સાચવો કે તરત જ Slack તેને વેરિફાય કરે છે, તેથી આ સર્વર ઇન્ટરનેટ પરથી પહોંચી શકાય તેવું હોવું જોઈએ.',
        'slack_step5' => 'Slackમાં, જે ચેનલ પર તેને જોવું છે ત્યાં appને આમંત્રિત કરો: <strong>/invite @YourApp</strong>. તે જે ચેનલમાં ન હોય તે વાંચી શકતું નથી.',
    ],
