        'heading' => 'પોર્ટલ પર સર્વિસ સ્ટેટસ',
        'intro' => 'End users પહેલેથી જ સ્વ-સેવા પોર્ટલમાં જુએ છે કે કઈ સેવાઓ સ્વસ્થ છે. આ નક્કી કરે છે કે તેઓ આઉટેજ પાછળના <strong>incidents</strong> પણ જુએ છે કે નહીં, અને તમારી ટીમે external તરીકે માર્ક કરેલા અપડેટ્સ પણ.',
        'warning' => '<strong>આને ચાલુ કરતાં પહેલાં આ વાંચો.</strong> Incident શીર્ષકો તમારી ટીમ માટે લખાયેલા હતા, ગ્રાહકો માટે નહીં &mdash; end users તે વાંચવાનું શરૂ કરે તે પહેલાં તપાસો કે તમારા શીર્ષકોમાં શું લખેલું છે. ફક્ત <strong>external</strong> તરીકે સ્પષ્ટ માર્ક કરેલા અપડેટ્સ જ ક્યારેય બતાવાય છે; આ ફીચર અસ્તિત્વમાં આવ્યું તે પહેલાં લખાયેલું બધું internal છે, અને internal જ રહે છે.',
