        'conns_desc' => 'FreeITSM વિશ્લેષકોના પોતાના કેલેન્ડરમાં ઇવેન્ટ કેવી રીતે લખે છે. જરૂર હોય તેટલા ઉમેરો - Microsoft 365, એક કે વધુ CalDAV સર્વર, અથવા બંને. દરેક વિશ્લેષક <strong>Preferences &rarr; My work calendar</strong> હેઠળ પસંદ કરે છે કે તેમનું કામ કયામાં જાય.',
