        'provider_microsoft' => 'Microsoft 365 / Exchange',
        'provider_caldav_short' => 'CalDAV',
        'provider_caldav' => 'એક CalDAV સર્વર (Nextcloud, Baïkal, Radicale, iCloud, Fastmail…)',
        'caldav_desc' => 'FreeITSM દરેક વિશ્લેષકના શેડ્યુલ કરેલા કામને તમારા CalDAV સર્વર પરના કેલેન્ડરમાં લખે છે, <strong>એ વિશ્લેષક તરીકે સાઇન-ઇન થઈને</strong>. CalDAV સર્વર પર એક એકાઉન્ટ પાસે બધાના કેલેન્ડરમાં લખવાની કોઈ રીત નથી, એટલે અહીં પાસવર્ડ નથી: દરેક વિશ્લેષક પોતે સાઇન-ઇન કરે છે અને <strong>Preferences &rarr; My work calendar</strong> હેઠળ પોતાનું કેલેન્ડર પસંદ કરે છે.',
        'server_url' => 'સર્વર સરનામું',
        'server_url_hint' => 'સર્વરનું DAV સરનામું, તેનો વેબ પેજ નહીં. Baïkal: <code>https://server/dav.php/</code> &middot; Nextcloud: <code>https://server/remote.php/dav/</code> &middot; Radicale: <code>https://server/</code>. વિશ્લેષકો ફક્ત આ સર્વર પરના કેલેન્ડર જ પસંદ કરી શકે છે.',
        'caldav_auth' => 'સાઇન-ઇન પદ્ધતિ',
        'auth_auto' => 'ઑટોમેટિક (ભલામણ કરેલ)',
        'auth_digest' => 'Digest',
        'auth_basic' => 'Basic',
        'caldav_auth_hint' => 'કોઈ કારણ ન હોય ત્યાં સુધી તેને Automatic પર જ રહેવા દો. સ્ટાન્ડર્ડ Baïkal ને Basicને બદલે Digest જોઈએ છે, અને Automatic સર્વરને પૂછે છે કે તે કયું ઑફર કરે છે.',
        'caldav_probe' => 'સાઇન-ઇન અજમાવો (વૈકલ્પિક, ફક્ત આ ટેસ્ટ માટે વપરાય છે અને સાચવવામાં આવતું નથી)',
        'probe_user' => 'વપરાશકર્તાનામ',
