        'caldav_test_ok' => 'કનેક્ટ થયું. તે સરનામું એક કેલેન્ડર સર્વર છે.',
        'caldav_test_failed_hint' => 'ચકાસો કે સરનામું સર્વરના વેબ પેજને બદલે તેનો DAV પાથ છે, અને FreeITSM નેટવર્ક પર તેના સુધી પહોંચી શકે છે.',
