        'caldav_probe_bad' => '{user} તરીકે સાઇન-ઇન કરવું નિષ્ફળ ગયું: {error}',
        'caldav_probe_auth' => 'સર્વરે {auth} ઓથેન્ટિકેશન ઑફર કર્યું.',
        'caldav_no_notify' => 'CalDAV સર્વર ચેન્જ નોટિફિકેશન મોકલતા નથી, એટલે કેલેન્ડરમાં કરેલા ફેરફાર શેડ્યુલ્ડ જોબ ચાલે ત્યારે પહોંચે છે.',
        'people_desc_caldav' => 'દરેક વિશ્લેષક CalDAV સર્વરમાં સાઇન-ઇન કરે છે અને Preferences હેઠળ પોતાનું કેલેન્ડર પસંદ કરે છે. એડમિનિસ્ટ્રેટર તેમના માટે તે પસંદ કરી શકતા નથી, કારણ કે ફક્ત વિશ્લેષક પાસે જ તેના સુધી પહોંચતો પાસવર્ડ છે.',
        'no_account' => 'સાઇન-ઇન નથી',
        'switch_title' => 'આ કનેક્શન ક્યાં લખે છે તે બદલવું?',
        'switch_confirm' => 'આ કનેક્શને વિશ્લેષકોના કેલેન્ડરમાં મૂકેલા {mapped} ઇવેન્ટ(ટ્સ) પાછા લેવાશે, અને તેનો ઉપયોગ કરતા {pushing} વિશ્લેષક(કો) માટે કેલેન્ડર સિંક બંધ થશે, જેથી દરેક તેને ફરી સેટ કરી શકે. બીજા કનેક્શન પરના વિશ્લેષકો, અને સબસ્ક્રિપ્શન લિંક, અસરગ્રસ્ત થતા નથી.',
        'switch_ok' => 'બદલો',
        'switch_done' => 'સાચવાયું. આ કનેક્શન પરના વિશ્લેષકો માટે કેલેન્ડર સિંક રીસેટ થયું છે.',
        'perm_title' => 'આ કામ કરે તે પહેલાં',
        'perm_body' => 'એપ રજિસ્ટ્રેશનને <strong>Application</strong> પરમિશન તરીકે <strong>Calendars.ReadWrite</strong> જોઈએ છે (Delegated નહીં — Azure માં તે અલગ લિસ્ટ છે), એડમિન કન્સેન્ટ સાથે. ધ્યાન રાખો કે આ પરમિશન FreeITSM ને <strong>ટેનન્ટના દરેક મેઇલબોક્સ</strong>માં લખવા દે છે. જો આ તમે આપવા માંગો છો તેના કરતાં વધુ હોય, તો Exchange Online માં Application Access Policy નો ઉપયોગ કરીને એપને તમારા એનાલિસ્ટના mail-enabled સિક્યુરિટી ગ્રુપ સુધી સ્કોપ કરો.',
        'name' => 'નામ',
        'source_mailbox' => 'મેઇલબોક્સમાંથી ક્રેડેન્શિયલ્સ ઉધાર લો',
        'source_own' => 'ક્રેડેન્શિયલ્સ દાખલ કરો',
        'mailbox' => 'મેઇલબોક્સ',
        'no_mailboxes' => 'આ સિસ્ટમ પરના કોઈપણ Microsoft મેઇલબોક્સ પાસે ઉધાર લેવા માટે Azure ક્રેડેન્શિયલ્સ નથી, તેથી નીચે તે દાખલ કરો. જો તમારા એનાલિસ્ટના કેલેન્ડર તમારા ઇનટેક મેઇલબોક્સ કરતાં અલગ ટેનન્ટમાં હોય, અથવા તમારું ઇનટેક Microsoft નું જ ન હોય, તો આ સામાન્ય છે.',
