        'test_ok' => 'કનેક્ટ થયું. ક્રેડેન્શિયલ્સ કામ કરે છે અને પરમિશન આપવામાં આવેલ છે.',
        'test_borrowed' => 'મેઇલબોક્સ "{name}" માંથી એપ રજિસ્ટ્રેશન વાપરી રહ્યાં છીએ.',
        'test_failed' => 'કનેક્ટ થઈ શકાયું નથી.',
