        'probe_ok' => '{addr} પાસે એક કેલેન્ડર છે જેમાં FreeITSM લખી શકે છે.',
        'probe_bad' => '{addr} માટે કોઈ કેલેન્ડર મળ્યું નથી. ચકાસો કે સરનામું આ ટેનન્ટમાં એક વાસ્તવિક મેઇલબોક્સ છે — એનાલિસ્ટનું FreeITSM ઈમેલ સરનામું હંમેશા તેમનું મેઇલબોક્સ સરનામું હોતું નથી.',
        'conn_delete_confirm' => '“{name}” કાઢી નાખવું?',
        'conn_delete_title' => 'આ કનેક્શન કાઢી નાખવું?',
        'conn_delete_used' => 'FreeITSM આ કનેક્શને વિશ્લેષકોના કેલેન્ડરમાં મૂકેલા {mapped} ઇવેન્ટ(ટ્સ) પાછા લે છે, અને તેનો ઉપયોગ કરતા {pushing} વિશ્લેષક(કો) માટે કેલેન્ડર સિંક બંધ કરે છે. બીજા કનેક્શન પરના વિશ્લેષકો અસરગ્રસ્ત થતા નથી.',
        'conn_deleted' => 'કનેક્શન કાઢી નાખ્યું',
        'people_heading' => 'દરેક એનાલિસ્ટ કયા મેઇલબોક્સ સાથે સિંક કરે છે',
        'people_desc' => 'ડિફૉલ્ટ રીતે FreeITSM એનાલિસ્ટના એકાઉન્ટ પરના ઈમેલ સરનામાનો ઉપયોગ કરે છે, જે ઘણી વખત તેમનું મેઇલબોક્સ હોતું નથી — સ્થાનિક એકાઉન્ટ, અથવા બીજી કોઈ વસ્તુ પર આધારિત ડિરેક્ટરી ઇમ્પોર્ટ. તેને અહીં ઓવરરાઇડ કરો. એનાલિસ્ટ પસંદ કરે છે કે તેમનું કામ <em>સિંક થાય કે નહીં</em>; ફક્ત એડમિનિસ્ટ્રેટર જ પસંદ કરે છે કે તે <em>ક્યાં</em> જાય છે.',
        'col_analyst' => 'એનાલિસ્ટ',
        'col_status' => 'એનાલિસ્ટ દ્વારા પસંદ કરેલ',
        'check_save' => 'ચકાસો અને સાચવો',
        'mode_off' => 'બંધ',
        'mode_push' => 'સિંક થઈ રહ્યું છે',
        'mode_feed' => 'સબ્સ્ક્રાઇબ થયેલ',
        'mode_error' => 'છેલ્લું સિંક નિષ્ફળ ગયું',
        'tasks_work' => 'કાર્યો: આયોજિત',
        'tasks_due' => 'કાર્યો: નિયત તારીખો',
        'tasks_both' => 'કાર્યો: બંને',
        'tasks_note' => 'આ એનાલિસ્ટે પોતાના કાર્યોનો સમાવેશ કરવાનું પસંદ કર્યું છે. તેઓ આ Preferences હેઠળ પોતે પસંદ કરે છે; અહીં તેમના માટે તે સેટ કરી શકાતું નથી.',
        'saved_unverified' => 'સાચવ્યું. કનેક્શન કામ કરતું ન હોવાથી સરનામું ચકાસી શકાયું નથી — ઉપર તેને ટેસ્ટ કરો.',
        'inbound_heading' => 'કેલેન્ડરમાં કરેલા ફેરફારો',
        'inbound_desc' => 'Outlook માં આમાંથી કોઈ એક એપોઇન્ટમેન્ટ ખસેડો અને ટિકિટ પણ તેને અનુસરશે. આ માટે <code>cron/calendar_sync_pull.php</code> જોબ ચાલવી જરૂરી છે — દર 5 મિનિટ યોગ્ય છે. તેના વગર સિંક ફક્ત એક દિશામાં થાય છે, જે આજે બરાબર આ રીતે કામ કરે છે.',
        'accept_deletes' => 'એપોઇન્ટમેન્ટ ડિલીટ કરવાથી ટિકિટ અનશેડ્યુલ થાય છે',
        'notify_url' => 'નોટિફિકેશન URL (વૈકલ્પિક)',
        'notify_url_note' => 'ફક્ત શેડ્યુલ્ડ ચેક પર આધાર રાખવા ખાલી રાખો, જે એકદમ બરાબર છે — ફેરફારો પછી થોડી મિનિટોમાં આવે છે. તેને ભરો અને જ્યારે કંઈ બદલાય ત્યારે Microsoft તરત જ FreeITSM ને જણાવશે, તેથી તે સેકન્ડોમાં પહોંચે છે. તે <strong>ઇન્ટરનેટ પરથી Microsoft પહોંચી શકે તેવું HTTPS સરનામું</strong> હોવું જોઈએ, જે <code>/api/calendar/graph_notify.php</code> સાથે સમાપ્ત થાય. કોઈપણ રીતે શેડ્યુલ્ડ જોબ હજુ પણ જરૂરી છે: તે સબ્સ્ક્રિપ્શન રિન્યુ કરે છે, અને એક ચૂકી ગયેલી નોટિફિકેશન જે ગુમાવી શકે તે પકડે છે.',
        'notify_suggest' => 'આ સરનામું વાપરો',
        'notify_suggest_note' => 'તમે હમણાં વાપરી રહ્યાં છો તે સરનામામાંથી ભરાયેલ છે. ચકાસો કે તે બહારથી પહોંચી શકાય તેવું છે — પ્રોક્સી અથવા ટનલ પાછળ ઘણી વખત તે નથી હોતું, અને ખોટું સરનામું સરનામા વિશેને બદલે validation વિશેના મેસેજ સાથે નિષ્ફળ જાય છે.',
        'notify_saved' => 'શેડ્યુલ્ડ જોબ તેના આગલા run પર સબ્સ્ક્રિપ્શન બનાવશે અથવા અપડેટ કરશે.',
        'notify_active' => '{n} સબ્સ્ક્રિપ્શન સક્રિય',
