        'health_never' => 'કેલેન્ડર ક્યારેય ચકાસાયા નથી.',
        'health_stale_note' => 'Outlook માં કરેલા ફેરફારો ત્યારે આવે છે જ્યારે શેડ્યુલ્ડ જોબ ચાલે છે, તેથી સામાન્ય રીતે તેનો અર્થ એ છે કે તે બંધ થઈ ગયું છે — ચકાસો કે <code>cron/calendar_sync_pull.php</code> હજુ પણ પોતાના શેડ્યુલ પર ચાલી રહ્યું છે. તે સબ્સ્ક્રિપ્શન પણ રિન્યુ કરે છે, તેથી તે બંધ થયાના થોડા દિવસો પછી નોટિફિકેશન બંધ થાય છે. જો તમે ઇરાદાપૂર્વક તેને દર અડધા કલાકે કરતાં ઓછી વાર ચલાવો છો, તો આ અપેક્ષિત છે.',
