        'sub_lapsed' => 'સબ્સ્ક્રિપ્શન સમાપ્ત થયું',
        'accept_deletes_note' => 'ડિફૉલ્ટ રીતે બંધ. તેને ચાલુ કરવાથી, જે એનાલિસ્ટ પોતાના ફોન પર આમાંથી એક ડિલીટ કરે છે તેને બેસે ત્યારે ટિકિટ પહેલેથી જ અનશેડ્યુલ્ડ મળે છે — જે ઘણી વખત તેનો હેતુ જ હોય છે. આવો દરેક ફેરફાર ટિકિટના ઇતિહાસમાં લખાય છે, અને એકસાથે અસામાન્ય રીતે મોટી સંખ્યામાં ડિલીશન પાળવાને બદલે નકારવામાં આવે છે, કારણ કે તે સૂચનાને બદલે ખામી હોવાની શક્યતા વધુ છે. તેને બંધ રાખવાથી, ડિલીટ કરેલી એપોઇન્ટમેન્ટ આગલી વખતે ટિકિટ બદલાય ત્યારે ફરીથી દેખાય છે.',
