        'feed_desc' => 'એનાલિસ્ટ પોતાનું શેડ્યુલ કરેલું કામ કેલેન્ડર સબ્સ્ક્રિપ્શન લિંક તરીકે પબ્લિશ કરી શકે છે, જે કોઈપણ કેલેન્ડર એપ સાથે કામ કરે છે. લિંક એ લોગ ઇનને બદલે એક ગુપ્ત URL છે, તેથી તે ધરાવનાર કોઈપણ વ્યક્તિ તે જે બતાવે છે તે વાંચી શકે છે.',
