        'search_dismiss_desc' => 'સર્ચ પેનલને ખસેડીને ખુલ્લી રાખી શકાય છે, એટલે ડિફોલ્ટ રીતે ફક્ત તેનું ✕ કે Escape કી જ તેને બંધ કરે છે. તમે ક્યાંક બીજે ક્લિક કરો કે તરત તે બંધ થાય — ફોલ્ડર યાદી, ટિકિટ યાદી કે ટૂલબાર પર — તે માટે આ ચાલુ કરો. તમે હમણાં જ શોધેલી ટિકિટ, કે તેની પ્રોપર્ટીઝ ક્લિક કરવાથી પેનલ હજુ ખુલ્લી રહે છે, જેથી પરિણામ પર કાર્યવાહી કર્યા પછી પણ સર્ચ યથાવત્ રહે.',
        'search_dismiss_label' => 'હું ક્યાંક બીજે ક્લિક કરું ત્યારે તેને બંધ કરો',
