        'taskcal_due' => 'જ્યારે તે નિયત હોય',
        'taskcal_both' => 'બંને',
        'taskcal_note' => 'એક કાર્ય તમારા કેલેન્ડરમાં બે વસ્તુઓ મૂકી શકે છે: તમે તે કરવા માટે અલગ રાખેલો સમય, સામાન્ય એપોઇન્ટમેન્ટ તરીકે, અને તેની નિયત તારીખ, all-day એન્ટ્રી તરીકે. પૂર્ણ થયેલા કાર્યો દૂર કરવામાં આવે છે, અને તમને બદલે ટીમને સોંપાયેલું કાર્ય ક્યારેય ઉમેરાતું નથી.',
