        'workcal_push_caldav_where' => 'તમારી શેડ્યુલ કરેલી ટિકિટો તમારા કેલેન્ડર “{name}”માં લખાશે.',
        'caldav_intro' => '{server} પર તમારા કેલેન્ડરમાં સાઇન-ઇન કરો અને તમારું શેડ્યુલ કરેલું કામ કયા કેલેન્ડરમાં જવું જોઈએ તે પસંદ કરો. FreeITSM તમારા તરીકે સાઇન-ઇન થાય છે, એટલે તે ફક્ત તમે પહોંચી શકો તે કેલેન્ડર સુધી જ પહોંચી શકે છે.',
