        'caldav_forget_confirm' => 'FreeITSM તમારા કેલેન્ડરમાંથી પોતાના ઇવેન્ટ પાછા લઈ લેશે, પછી તમારું સાઇન-ઇન ભૂલી જશે અને આ બંધ કરી દેશે.',
