        'workcal_reset_confirm' => 'પહેલેથી સબ્સ્ક્રાઇબ થયેલ દરેક ડિવાઇસ તમે તેને નવી લિંક ન આપો ત્યાં સુધી અપડેટ થવાનું બંધ કરી દેશે. ચાલુ રાખવું છે?',
