        'landing_desc' => 'લોગ ઇન કર્યા વગર FreeITSM ખોલો ત્યારે તમને ક્યાં મોકલવામાં આવે છે.',
        'landing_default' => 'સાઇટ ડિફૉલ્ટ વાપરો ({name})',
