        'modorder_desc' => 'તમારા વેફલ મેનૂમાં, હોમ પેજ પર અને Ctrl+K "Go to" યાદીમાં મોડ્યુલનો ક્રમ. મોડ્યુલને તેના હેન્ડલથી ખેંચો, તીરનો ઉપયોગ કરો, અથવા એક પસંદ કરો અને ઉપર અથવા નીચેના તીર સાથે Alt દબાવો. આ ક્રમ ફક્ત તમે જ જુઓ છો.',
        'modorder_note' => 'તમે કરો તેમ સાચવાય છે, અને તમે ખોલશો તે આગલા પેજથી વપરાય છે. પછીના અપડેટમાં ઉમેરાયેલું મોડ્યુલ આપોઆપ યાદીમાં જોડાય છે.',
