        'selfreg_desc' => 'લોકો સાઇન-ઇન પેજ પરથી પોતાનું સ્વ-સેવા પોર્ટલ એકાઉન્ટ બનાવી શકે કે નહીં. ડિફોલ્ટ રીતે બંધ. ચાલુ હોય ત્યારે પણ, કોઈ પાસવર્ડ સેટ થાય તે પહેલાં સાઇન-અપ ઈમેઇલ લિંકથી કન્ફર્મ કરવું જરૂરી છે.',
