        'selfreg_hint' => 'બંધ = કોઈ પોતાનું એકાઉન્ટ બનાવી શકતું નથી. તમે ઉમેરેલા લોકો હજુ પણ સાઇન-ઇન કરી શકે છે — તેઓ પોર્ટલ સાઇન-ઇન પેજ પર "Forgot your password?" વાપરીને પોતાનો પહેલો પાસવર્ડ સેટ કરે છે.',
        'trusted_heading' => 'ટ્રસ્ટેડ ડિવાઇસ',
        'trusted_desc' => 'વપરાશકર્તાઓને ટ્રસ્ટેડ બ્રાઉઝર પર OTP વેરિફિકેશન છોડવાની મંજૂરી આપો. વપરાશકર્તાઓ પોતાના અવતાર મેનુ દ્વારા વ્યક્તિગત રીતે તેમાં જોડાય છે. આ ફીચર સંપૂર્ણપણે બંધ કરવા 0 સેટ કરો.',
        'trust_duration' => 'ટ્રસ્ટનો સમયગાળો',
        'trust_duration_hint' => 'OTP વેરિફિકેશન પછી ડિવાઇસ કેટલો સમય ટ્રસ્ટેડ રહે છે',
        'password_heading' => 'પાસવર્ડ પોલિસી',
        'password_desc' => 'વપરાશકર્તાઓને સમયાંતરે તેમનો પાસવર્ડ બદલવો ફરજિયાત બનાવો. પાસવર્ડ એક્સપાયર થાય ત્યારે, વપરાશકર્તાને આગલા લોગિન વખતે ફરજિયાત પાસવર્ડ બદલવાની સ્ક્રીન પર રીડાયરેક્ટ કરવામાં આવે છે. બંધ કરવા 0 સેટ કરો.',
        'password_expiry' => 'પાસવર્ડ એક્સપાયરી',
        'password_expiry_hint' => 'પાસવર્ડ બદલવો ફરજિયાત બને તે પહેલાંની મહત્તમ ઉંમર',
        'lockout_heading' => 'એકાઉન્ટ લોકઆઉટ',
        'lockout_desc' => 'બ્રુટ-ફોર્સ હુમલા અટકાવવા વારંવાર નિષ્ફળ લોગિન પ્રયાસો પછી એકાઉન્ટ લોક કરો. લોકઆઉટ બંધ કરવા મહત્તમ પ્રયાસ 0 સેટ કરો.',
        'max_attempts' => 'મહત્તમ નિષ્ફળ પ્રયાસો',
        'max_attempts_hint' => 'એકાઉન્ટ લોક થાય તે પહેલાં ખોટા પાસવર્ડની સંખ્યા',
        'lockout_duration' => 'લોકઆઉટનો સમયગાળો',
        'lockout_duration_hint' => 'એકાઉન્ટ કેટલો સમય લોક રહે છે (અનલોક પછી કાઉન્ટર રીસેટ થાય છે)',
        'ipban_heading' => 'IP બેન',
        'ipban_desc' => 'ન હોય તેવા કે લોક થયેલા એકાઉન્ટ સામે વારંવાર લોગિન પ્રયાસ કરતા IP સરનામાંને આપમેળે બેન કરો. દરેક બેન 24 કલાક ચાલે છે. દરેક બેન પછી થ્રેશોલ્ડ 1 થી ઘટે છે (ન્યૂનતમ સુધી), જેથી વારંવાર ગુનો કરનારાઓ માટે દુરુપયોગ કરવો વધુ મુશ્કેલ બને છે. બંધ કરવા મહત્તમ પ્રયાસ 0 સેટ કરો.',
        'first_ban' => 'પહેલા બેનનો થ્રેશોલ્ડ',
        'first_ban_hint' => 'IP પહેલી વાર બેન થાય તે પહેલાંના નિષ્ફળ પ્રયાસો',
        'min_threshold' => 'ન્યૂનતમ થ્રેશોલ્ડ',
        'min_threshold_hint' => 'આ ફ્લોર સુધી પહોંચ્યા પછી થ્રેશોલ્ડ ઘટવાનું બંધ થાય છે',
        'ipban_example_strong' => 'ઉદાહરણ:',
        'ipban_example_text' => 'મહત્તમ 5 અને ન્યૂનતમ 2 સાથે, પહેલો બેન 5 નિષ્ફળ પ્રયાસો પછી, બીજો 4 પછી, પછી 3, પછી 2 પછી ટ્રિગર થાય છે. ત્યારપછીના દરેક બેન માટે તે 2 પર જ રહે છે. ફક્ત ન હોય તેવા યુઝરનેમ કે પહેલેથી લોક થયેલા એકાઉન્ટ સામેના પ્રયાસો જ ગણાય છે.',
        'attachments_heading' => 'જોડાણો',
        'attachments_desc' => 'FreeITSM ફક્ત તે ઓળખે તેવા જોડાણ પ્રકારો જ સ્વીકારે છે. બીજું કંઈ પણ — પ્રોગ્રામ, સ્ક્રિપ્ટ, વેબ પેજ — ક્યારેય તેના પોતાના નામ હેઠળ સંગ્રહાતું નથી, એટલે તેને ચલાવી શકાતું નથી.',
        'rejected_behaviour' => 'ફાઇલ પ્રકાર સ્વીકારવામાં ન આવે ત્યારે',
        'rejected_behaviour_hint' => 'ઈમેઇલ, પોર્ટલ અને ચેટ ચેનલોને લાગુ પડે છે.',
        'rejected_store' => 'રાખો, ફક્ત ડાઉનલોડ કરી શકાય',
        'rejected_drop' => 'રાખશો નહીં',
        'allowed_extensions' => 'સ્વીકૃત ફાઇલ પ્રકારો',
        'allowed_extensions_hint' => 'FreeITSM જેને સુરક્ષિત ગણે તે બધું જ સ્વીકારવા ખાલી રાખો, જેમાં ભવિષ્યના અપડેટ્સ ઉમેરે તેવા નવા પ્રકારો પણ સામેલ છે. ઓછું સ્વીકારવા, ફક્ત તમને જોઈતા એક્સટેન્શન કોમાથી અલગ કરીને લખો.',
        'allowed_extensions_ph' => 'દા.ત. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'તમે આ યાદીને ફક્ત સાંકડી જ કરી શકો છો. FreeITSM પહેલેથી સુરક્ષિત ન ગણતું હોય તેવું એક્સટેન્શન અવગણવામાં આવે છે, એટલે અહીં લખેલું કંઈ પણ પ્રોગ્રામ કે સ્ક્રિપ્ટને સ્વીકાર્ય બનાવી શકતું નથી.',
        'rejected_note' => 'બંને કિસ્સામાં ટિકિટ જણાવે છે કે શું થયું અને શા માટે, જેથી કોઈને પોતાની ફાઇલ ક્યાં ગઈ તે વિચારવું ન પડે.',
        'max_attachment' => 'સૌથી મોટું જોડાણ',
        'max_attachment_hint' => 'કોઈ એક જોડાણ આનાથી મોટું ન હોઈ શકે - ઈમેઇલ, પોર્ટલ, ચેટ ચેનલો, જવાબો અને જોડેલા દસ્તાવેજોમાં. તમે બદલો નહીં ત્યાં સુધી 10 MB.',
        'max_total' => 'સૌથી મોટો ઈમેઇલ',
        'max_total_hint' => 'એક આવતા ઈમેઇલના બધા જોડાણો મળીને. 0 એટલે ઉપરની મર્યાદા સિવાય કોઈ મર્યાદા નહીં.',
        'php_limits' => 'આ સર્વર પરનું PHP બ્રાઉઝર અપલોડ પ્રતિ ફાઇલ {upload} સુધી અને પ્રતિ વિનંતી {post} સુધી સ્વીકારે છે (php.ini માં upload_max_filesize અને post_max_size), અને તેની પાસે કામ કરવા {memory} મેમરી છે. જે ફાઇલ PHP નકારે તે FreeITSM સુધી પહોંચતી નથી, તેથી આનાથી ઉપરની મર્યાદા ફક્ત ઈમેઇલને જ મદદ કરે છે. આગળ રહેલું વેબ સર્વર કે પ્રોક્સી (nginx client_max_body_size, IIS maxAllowedContentLength) પોતાની નીચી મર્યાદા સેટ કરી શકે છે.',
        'php_limits_warn' => 'સૌથી મોટું જોડાણ PHP બ્રાઉઝરમાંથી સ્વીકારે છે તેનાથી વધારે છે: php.ini માં upload_max_filesize અને post_max_size પણ વધારો, નહીં તો FreeITSM મારફતે અપલોડ થતી ફાઇલો પહોંચતા પહેલાં જ નકારાશે.',
        'php_unlimited' => 'કોઈ મર્યાદા નથી',
        'oversize_signpost' => 'આ મર્યાદાથી મોટા આવતા ઈમેઇલનું શું થાય - તેને નકારવો, અથવા ખૂબ મોટા જોડાણો વિના રાખવો, અને કોને જણાવવું - તે {link} માં સેટ થાય છે. દરેક મેઈલબોક્સ ત્યાં પોતાની મર્યાદા પણ સેટ કરી શકે છે.',
        'oversize_signpost_link' => 'Tickets -> Settings -> Mailboxes',
        'unit_days' => 'દિવસો',
