        'save' => 'સાચવો',
        'saved' => 'સુરક્ષા સેટિંગ્સ સાચવાઈ',
        'error' => 'ભૂલ: {error}',
        'save_failed' => 'સેટિંગ્સ સાચવવામાં નિષ્ફળ',
