    'sso' => [
        'title' => 'પ્રમાણીકરણ',
        'subtitle' => 'યુઝર્સને Keycloak, Microsoft Entra, Okta અથવા Google જેવા બાહ્ય ઓળખ પ્રોવાઇડર (OpenID Connect) દ્વારા, અથવા તમારા LDAP / Active Directory સામે લોગ ઇન કરવા દો - સ્થાનિક એકાઉન્ટ્સની સાથે.',
        'global_heading' => 'ગ્લોબલ સેટિંગ્સ',
        'global_desc' => 'સમગ્ર સિસ્ટમમાં લોગ ઇન માટેના મુખ્ય નિયંત્રણો.',
        'enable_sso' => 'SSO સક્ષમ કરો',
        'enable_sso_desc' => 'લોગ ઇન પેજ પર કન્ફિગર કરેલા પ્રોવાઇડર બટન બતાવો. બધે જ તરત સ્થાનિક લોગ ઇન પર પાછા જવા માટે બંધ કરો (break-glass).',
        'allow_local' => 'સ્થાનિક લોગ ઇનની મંજૂરી આપો',
        'allow_local_desc' => 'વપરાશકર્તાનામ + પાસવર્ડ ફોર્મ ઉપલબ્ધ રાખો. ચાલુ રાખો જેથી ખોટી રીતે કન્ફિગર થયેલ અથવા ડાઉન પ્રોવાઇડર ક્યારેય બધાને લોક આઉટ ન કરે.',
        'global_load_failed' => 'આ સેટિંગ્સ વાંચી શકાયા નથી.',
        'global_load_failed_desc' => 'નીચેના સ્વિચ તમારા વાસ્તવિક સેટિંગ્સ બતાવી રહ્યા નથી, તેથી ખોટી વેલ્યુ ઉપર સેવ થતી અટકાવવા તેમને લોક કરવામાં આવ્યા છે. કંઈ બદલાયું નથી.',
        'retry' => 'ફરી પ્રયાસ',
        'save' => 'સાચવો',
        'redirect_heading' => 'Redirect URI',
        'redirect_desc' => 'દરેક ઓળખ પ્રોવાઇડરમાં આ ચોક્કસ URL ને મંજૂર redirect / callback URL તરીકે રજિસ્ટર કરો. યુઝર્સ લોગ ઇન કર્યા પછી પ્રોવાઇડર તેમને અહીં પાછા મોકલે છે.',
        'signout_heading' => 'સાઇન-આઉટ સરનામાં',
        'signout_desc' => 'દરેક આઇડેન્ટિટી પ્રોવાઇડરમાં બંનેને માન્ય સાઇન-આઉટ (પોસ્ટ-લોગઆઉટ) રીડાયરેક્ટ URL તરીકે નોંધો. FreeITSM માંથી સાઇન આઉટ કરવાથી લોકો પ્રોવાઇડરમાંથી પણ સાઇન આઉટ થાય છે, જે પછી તેમને આમાંથી કોઈ એક પર પાછા મોકલે છે. Keycloak અને Okta યાદીમાં બરાબર ન હોય તેવા કોઈપણ સરનામાંને નકારે છે.',
        'signout_analyst' => 'વિશ્લેષક લોગિન',
        'signout_portal' => 'સ્વ-સેવા પોર્ટલ',
