        'cb_verified_desc' => 'જ્યાં સુધી પ્રોવાઇડર {claim} ન મોકલે ત્યાં સુધી લોગ ઇનનો ઇનકાર કરો. જે પ્રોવાઇડર claim સંપૂર્ણપણે છોડી દે છે (દા.ત. Okta નું org સર્વર) તેમના માટે બંધ રાખો. આ સેટિંગને ધ્યાનમાં લીધા વગર સ્પષ્ટ {claim_false} હંમેશા નકારવામાં આવે છે. ફક્ત એવા IdP માટે ચાલુ કરો જ્યાં યુઝર્સ અસત્યાપિત સરનામાં સાથે સેલ્ફ-રજિસ્ટર કરી શકે.',
