        'group_unseen_tag' => 'હજુ સુધી કોઈ સાઇન-ઇનમાં જોવાયું નથી',
        'group_name_ph' => 'તેને નામ આપો, દા.ત. IT સ્ટાફ',
        'field_groups_seen' => 'જોવાયેલા ગ્રુપ',
        'field_groups_seen_hint' => 'આ પ્રોવાઇડરે સાઇન-ઇન વખતે મોકલેલા દરેક ગ્રુપ. Microsoft જેવા કેટલાક પ્રોવાઇડર નામને બદલે કોડ મોકલે છે - દરેકને અહીં નામ આપો અને નીચેના ડ્રોપડાઉન નામ બતાવશે. કોડ તમારા પ્રોવાઇડરમાં ગ્રુપના નામની બાજુમાં મળશે (Microsoft Entra માં: Groups, ગ્રુપ, Object ID).',
