        'field_claim_analyst_group' => 'વિશ્લેષક ગ્રુપ',
        'field_claim_analyst_group_hint' => 'ફક્ત આ ગ્રુપના લોકો જ વિશ્લેષક તરીકે સાઇન ઇન કરી શકે છે, અને ફક્ત તેમને જ આપોઆપ બનાવવામાં આવે છે. જે કોઈ તેમાંથી નીકળી જાય તેને પછીના સાઇન-ઇન વખતે નકારવામાં આવે છે. આ પ્રોવાઇડર જેને સાઇન ઇન કરાવે તે કોઈપણ વિશ્લેષક બની શકે, હાલની જેમ, તે માટે તેને ખાલી રાખો.',
        'field_claim_admin_group' => 'એડમિનિસ્ટ્રેટર ગ્રુપ',
        'field_claim_admin_group_hint' => 'આ ગ્રુપના લોકો એડમિનિસ્ટ્રેટર છે; તેમાં ન હોય તેઓ નથી. એડમિનિસ્ટ્રેટર જાતે સંભાળવા માટે તેને ખાલી રાખો. છેલ્લા એડમિનિસ્ટ્રેટરને ક્યારેય દૂર કરવામાં આવતા નથી.',
        'field_group_teams' => 'ટીમો',
        'field_group_teams_hint' => 'દરેક સાઇન-ઇન વખતે, લોકોને તેમના ગ્રુપ જે ટીમો તરફ ઇશારો કરે તેમાં ઉમેરવામાં આવે છે અને ગ્રુપ છોડે ત્યારે આ ટીમોમાંથી કાઢી નાખવામાં આવે છે. અહીં સૂચિબદ્ધ ન હોય તેવી ટીમો ક્યારેય બદલાતી નથી. આ પ્રોવાઇડર જે વિશ્લેષકો બનાવે તેમને મોડ્યુલ આ ટીમોમાંથી મળે છે.',
