        'claims_none_sent' => 'તે ભાગમાં કંઈ નથી',
        'claims_not_yet' => 'આ સેટ કર્યા પછી કોઈએ સાઇન ઇન કર્યું નથી, તેથી હજુ પસંદ કરવા માટે કોઈ ગ્રુપ નથી. આ પ્રોવાઇડર દ્વારા એક વાર સાઇન ઇન કરો, પછી પાછા આવો.',
        'field_default_modules_hint' => 'JIT દ્વારા બનેલા વિશ્લેષકોને આપવામાં આવતી મોડ્યુલ કીઝ, અલ્પવિરામથી અલગ કરેલી (દા.ત. {example}). {strong} — પાઇલટ માટે આ સેટ કરો જેથી આપોઆપ બનેલા વિશ્લેષકો એડમિન ન હોય.',
        'field_default_modules_strong' => 'ખાલી રાખો અને તેમને દરેક મોડ્યુલની સંપૂર્ણ એક્સેસ મળશે',
        'field_default_modules_placeholder' => 'tickets, knowledge',
        'field_company' => 'કંપની',
        'field_company_hint' => 'આ ઓળખ પ્રોવાઇડરની માલિકી કઈ ક્લાયન્ટ કંપની ધરાવે છે - તેના રિક્વેસ્ટર્સ સેલ્ફ-સર્વિસ પોર્ટલ પર અહીં રૂટ થાય છે. MSP-આંતરિક પ્રોવાઇડર માટે (દા.ત. એનાલિસ્ટ લોગ ઇન) ગ્લોબલ રાખો.',
        'field_company_global' => 'ગ્લોબલ (આંતરિક / બધા)',
        'field_portal_domains' => 'ઈમેઇલ ડોમેન',
        'field_portal_domains_hint' => 'દર લાઇનમાં એક, દા.ત. company.com. પોર્ટલ પર, આ ડોમેનમાંના કોઈ પરના ઈમેઇલ સરનામાને પહેલી વાર પણ સીધું આ પ્રોવાઇડર પાસે મોકલવામાં આવે છે. તેમાં આજે પાસવર્ડથી સાઇન ઇન કરતા લોકો પણ આવે છે. બાકીના બધાને હંમેશની જેમ પાસવર્ડ બોક્સ મળે છે. સબડોમેન માટે અલગ લાઇન જોઈએ. કોઈને પણ રૂટ ન કરવા માટે ખાલી રાખો.',
        'cb_portal_show_button' => 'પોર્ટલ લોગિન પર બટન બતાવો',
        'cb_portal_show_button_desc' => 'ફક્ત ઈમેઇલ બોક્સ ધરાવતા પેજ માટે ટિક કાઢી નાખો. ઉપરના ડોમેનના લોકો હજુ પણ તેના દ્વારા આ પ્રોવાઇડર સુધી પહોંચે છે. વિશ્લેષક લોગિન પર અસર થતી નથી.',
        'cancel' => 'રદ કરો',
        'field_protocol' => 'પ્રકાર',
        'field_protocol_hint' => 'લોકો આ પ્રોવાઇડર સાથે કેવી રીતે લોગ ઇન કરે છે.',
        'protocol_oidc' => 'OpenID Connect (SSO)',
        'protocol_ldap' => 'LDAP / Active Directory',
        'protocol_carddav' => 'CardDAV એડ્રેસ બુક (ફક્ત સંપર્કો, લોગ ઇન નહીં)',
        'field_carddav_url' => 'સર્વરનું સરનામું',
        'field_carddav_url_hint' => 'CardDAV પાથ, વેબ પેજ નહીં. Baikal, Nextcloud અથવા બીજા sabre/dav સર્વર પર તે સામાન્ય રીતે https://dav.example.com/dav.php/addressbooks/jsmith/ જેવું દેખાય છે - તેને એ લેવલ પર પોઇન્ટ કરો જ્યાં તમારી એડ્રેસ બુક્સ છે, અને Test connection જે મળે તે લિસ્ટ કરશે.',
        'field_carddav_username' => 'યુઝરનેમ',
