        'field_carddav_password' => 'પાસવર્ડ',
        'field_carddav_password_hint' => 'એન્ક્રિપ્ટેડ સ્ટોર થાય છે, અને એકવાર સેવ થયા પછી ફરી ક્યારેય બતાવવામાં આવતું નથી.',
        'carddav_password_stored_hint' => 'એક પાસવર્ડ સ્ટોર થયેલો છે. તેને રાખવા માટે ખાલી છોડો.',
        'field_carddav_auth' => 'પ્રમાણીકરણ',
        'field_carddav_auth_hint' => 'કોઈ કારણ ન હોય ત્યાં સુધી આને Automatic પર રાખો. સ્ટાન્ડર્ડ Baikal સહિત મોટાભાગના સર્વર Basic ને બદલે Digest ઇચ્છે છે - Automatic સર્વરને પૂછે છે અને તે જે ઑફર કરે તેનો ઉપયોગ કરે છે.',
