        'field_carddav_book' => 'એડ્રેસ બુક',
        'field_carddav_book_hint' => 'કઈ એડ્રેસ બુકમાંથી સંપર્કો વાંચવા. Test connection દબાવો અને તમારું એકાઉન્ટ જે બુક્સ જોઈ શકે તેનાથી આ ભરાઈ જશે.',
        'carddav_book_untested' => 'તમારી એડ્રેસ બુક્સ જોવા માટે Test connection દબાવો',
        'carddav_book_required' => 'એક એડ્રેસ બુક પસંદ કરો. તેમને લિસ્ટ કરવા પહેલા Test connection દબાવો.',
        'carddav_url_required' => 'પહેલા તમારા CardDAV સર્વરનું સરનામું દાખલ કરો.',
        'carddav_test' => 'Test connection',
        'carddav_test_desc' => 'ચકાસે છે કે FreeITSM સર્વર સુધી પહોંચી શકે છે અને લોગ ઇન કરી શકે છે, અને તે જે એડ્રેસ બુક્સ જોઈ શકે તે લિસ્ટ કરે છે.',
        'carddav_test_desc_create' => 'ચકાસે છે કે FreeITSM સર્વર સુધી પહોંચી શકે છે અને આ વિગતો સાથે લોગ ઇન કરી શકે છે.',
        'carddav_test_next' => 'આને સાચવો, પછી એડ્રેસ બુક અને કયા સંપર્કો લાવવા તે પસંદ કરવા તેની રો પરના સેટિંગ્સ આઇકનનો ઉપયોગ કરો.',
        'carddav_page_sub' => 'એક CardDAV એડ્રેસ બુક. તેના દ્વારા કોઈ લોગ ઇન કરતું નથી - તે તમારા સર્વિસ ડેસ્કમાં સંપર્કો લાવે છે.',
        'tab_contacts' => 'સંપર્કો',
        'field_carddav_groups' => 'લાવવાના ગ્રુપ',
        'field_carddav_categories' => 'લાવવાના ટેગ',
        'carddav_pick_all' => 'બધા પસંદ કરો',
        'carddav_pick_none' => 'સાફ કરો',
        'carddav_pick_summary' => 'પસંદ કરેલા: {n}',
        'carddav_pick_summary_none' => 'હજુ સુધી કંઈ પસંદ કરેલું નથી.',
        'carddav_write_heading' => 'ફેરફારો પાછા મોકલવા',
        'carddav_write_hint' => 'સામાન્ય રીતે FreeITSM ફક્ત આ એડ્રેસ બુક વાંચે છે. આને ચાલુ કરો અને એનાલિસ્ટ સંપર્કના હોદ્દો, વિભાગ, ઓફિસ, ફોન અથવા મોબાઇલમાં કરેલો ફેરફાર તેમના કાર્ડ પર પણ લખાશે. તેમનો એમ્પ્લોયી ID અને મેનેજર FreeITSM માં જ રહે છે, કારણ કે સંપર્ક કાર્ડ પર તેમને રાખવા માટે કોઈ જગ્યા નથી.',
        'carddav_write_back' => 'FreeITSM માં કરેલા ફેરફારો એડ્રેસ બુકમાં પાછા લખો',
        'carddav_allow_create' => 'વિશ્લેષકોને આ એડ્રેસ બુકમાં લોકો ઉમેરવા દો',
        'carddav_allow_create_hint' => 'ડિફોલ્ટ રીતે બંધ. ચાલુ હોય ત્યારે, જે વ્યક્તિ કોઈ એડ્રેસ બુકમાં ન હોય તેને Tickets અને Assetsમાં Add to address book બટન મળે છે, જે અહીં તેમનું કાર્ડ બનાવીને તેમને લિંક કરે છે. કંઈ પણ લખતાં પહેલાં FreeITSM ચકાસે છે કે બુકમાં પહેલેથી કોઈની પાસે તેમનું ઈમેઇલ સરનામું નથી, અને પછી ચકાસે છે કે નવું કાર્ડ આ સ્રોત ઇમ્પોર્ટ કરે તેવું જ છે - તે જે ટૅગ કે ગ્રુપ વડે ઇમ્પોર્ટ કરે છે તે ઉમેરીને - અને જો ન હોય તો તેને ફરી દૂર કરે છે.',
        'carddav_write_warning' => 'ફક્ત ઉપર જણાવેલી વિગતો બદલાય છે, અને તે પણ ફક્ત જે સંપર્ક એડિટ થઈ રહ્યો છે તેના પર. કાર્ડ પરનું બીજું બધું - ફોટો, નોંધ, જન્મદિવસ, સંપૂર્ણ સરનામું, ગ્રુપ - બરાબર જેમ છે તેમ જ રહે છે. જો FreeITSM ના છેલ્લા ઇમ્પોર્ટ પછી કોઈએ એડ્રેસ બુકમાં એ જ વિગત બદલી હોય, તો તેમના પર ઓવરરાઇટ કરવાને બદલે ફેરફારનો ઇનકાર કરવામાં આવે છે.',
        'carddav_write_check' => 'પરવાનગી ચકાસો',
        'carddav_write_checking' => 'સર્વરને પૂછી રહ્યાં છીએ…',
        'carddav_write_check_failed' => 'પરવાનગીની ચકાસણી પૂર્ણ થઈ શકી નથી.',
        'carddav_writelog_heading' => 'પાછા મોકલેલા ફેરફારો',
        'carddav_writelog_hint' => 'દરેક વખતે જ્યારે FreeITSM એ સંપર્ક કાર્ડ અપડેટ કરવાનો પ્રયાસ કર્યો, અને શું થયું. નકારેલો ફેરફાર એ ખામી નથી - તેનો અર્થ એ છે કે કોઈએ પહેલેથી જ એડ્રેસ બુકમાં એ જ વિગત બદલી હતી, અને FreeITSM એ તેને ઓવરરાઇટ કરી નહીં.',
