        'openapi' => 'OpenAPI સ્પેસિફિકેશન',
        'mcp' => 'AI આસિસ્ટન્ટ કનેક્ટ કરો (MCP)',
        'mcp_desc' => 'FreeITSM <strong>Model Context Protocol</strong> બોલે છે, તેથી Claude Code અથવા Claude Desktop જેવા AI આસિસ્ટન્ટ તેને વાંચી શકે છે - પ્રોજેક્ટ, ખુલ્લી ઘટનાઓ, સેવા સ્થિતિ, ચેન્જ, એસેટ્સ અને વધુ. તે <strong>ફક્ત-વાંચવા માટે</strong> છે અને કીના વિશ્લેષક જે જોઈ શકે તે બરાબર જુએ છે: તેમના મોડ્યુલ અને કીની કંપનીઓ. <strong>MCP સર્વર</strong> પરવાનગી સાથે નીચે એક કી બનાવો અને આસિસ્ટન્ટને આ સરનામું આપો. <a href="https://github.com/edmozley/freeitsm/wiki/MCP-Server" target="_blank" rel="noopener">માર્ગદર્શિકા</a> જુઓ.',
