        'openapi_desc' => 'આખા API નું મશીન-વાંચી શકાય તેવું વર્ણન. તેને <strong>Postman</strong> અથવા <strong>Insomnia</strong> માં ઇમ્પોર્ટ કરો, ક્લાયન્ટ લાઇબ્રેરી જનરેટ કરો, અથવા કોઈપણ OpenAPI ટૂલને આપો &mdash; જેથી તમારે દરેક endpoint હાથે વાયર કરવું ન પડે. આમાં નવા છો? <a href="https://github.com/edmozley/freeitsm/wiki/REST-API-OpenAPI" target="_blank" rel="noopener">માર્ગદર્શિકા જુઓ</a>.',
