        'waiting_one' => '<strong>1</strong> webhook રાહ જોઈ રહ્યું છે &mdash; તે એક મિનિટમાં જતું રહેશે.',
        'waiting_many' => '<strong>{n}</strong> webhooks રાહ જોઈ રહ્યાં છે &mdash; તે એક મિનિટમાં જતાં રહેશે.',
        'nothing_waiting' => 'હાલમાં કંઈ રાહ જોઈ રહ્યું નથી.',
