        'down_explain' => '<strong>webhooks હવે મોકલાતાં નથી</strong> &mdash; worker છેલ્લે {when} ચાલ્યું અને બંધ થઈ ગયું હોય તેવું લાગે છે.',
        'stale_explain' => 'worker ચાલી રહ્યું છે પણ શેડ્યુલથી પાછળ છે (છેલ્લી વખત {when}). તે દર મિનિટે ચાલવું જોઈએ.',
        'queued_one' => '<strong>1</strong> webhook ક્યુમાં છે અને રાહ જોઈ રહ્યું છે.',
        'queued_many' => '<strong>{n}</strong> webhooks ક્યુમાં છે અને રાહ જોઈ રહ્યાં છે.',
        'step1' => '<strong>ડિલિવરી worker ને દર મિનિટે ચલાવવા માટે શેડ્યુલ કરો.</strong> સર્વર પર, આ કમાન્ડ શેડ્યુલ્ડ ટાસ્ક (Windows Task Scheduler) અથવા cron (Linux) માંથી ચલાવો:',
        'step1_http' => 'shell માંથી PHP ચલાવી શકતા નથી? તેના બદલે તેને HTTP પર કૉલ કરો (દા.ત. હોસ્ટેડ cron સેવામાંથી):',
        'step2' => '<strong>વર્કફ્લોમાં <em>Send a webhook</em> ક્રિયા ઉમેરો</strong> જેથી ઘટનાઓ ક્યુ ભરવાનું શરૂ કરે &mdash; <a href="{url}">વર્કફ્લો</a> હેઠળ.',
        'step3' => '<strong>આ પેજ પર નજર રાખો.</strong> worker ચાલે એટલે ઉપરની સ્થિતિ લીલી થાય છે અને ડિલિવરી નીચે દેખાય છે. સંપૂર્ણ સેટઅપ નોંધ (Windows &amp; Linux, signature verification) <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">Workflows wiki</a> માં છે.',
        'fact_worker' => 'Worker સ્ક્રિપ્ટ',
        'fact_retry' => 'ફરી પ્રયાસનું શેડ્યુલ',
