        'dp_title' => 'ડેટા સુરક્ષા',
        'dp_desc' => 'તમારા webhooks વિશે FreeITSM ડિસ્ક પર શું રાખે છે, અને કેટલા સમય સુધી.',
        'enc_on_title' => 'Webhook URL અને signing secret સંગ્રહમાં એન્ક્રિપ્ટેડ છે',
        'enc_on_body' => 'વર્કફ્લોમાં અને ડિલિવરી ક્યુમાં, AES-256-GCM સાથે સંગ્રહાય છે. Webhook URL પોતે જ એક ક્રેડેન્શિયલ છે &mdash; જેની પાસે તે હોય તે તમારી ચેનલ પર પોસ્ટ કરી શકે છે &mdash; અને signing secret એ સાબિત કરે છે કે સંદેશ ખરેખર તમારા તરફથી આવ્યો છે.',
        'enc_off_title' => 'કોઈ એન્ક્રિપ્શન કી ગોઠવેલ નથી &mdash; webhook URL અને signing secret સાદા ટેક્સ્ટમાં સંગ્રહાય છે',
        'enc_off_body' => 'એન્ક્રિપ્શન કી ફાઇલ હાજર હોય ત્યારે FreeITSM આને એન્ક્રિપ્ટ કરે છે, પણ આ ઇન્સ્ટોલ પર એકેય નથી, તેથી તમારા webhooks સાવ નિષ્ફળ કરવાને બદલે તે જેમ છે તેમ સાચવાય છે. ડેટાબેઝ અથવા તેનો બેકઅપ વાંચી શકનાર કોઈપણ તમારી ચેનલો પર પોસ્ટ કરી શકે છે અને તમારી signature બનાવટી બનાવી શકે છે. એન્ક્રિપ્શન કી (<code>ENCRYPTION_KEY_PATH</code>) ગોઠવો અને સંગ્રહાયેલી વેલ્યુ એન્ક્રિપ્ટ કરવા દરેક webhook વર્કફ્લો ફરી સાચવો.',
