        'ret_30' => '30 દિવસ',
        'ret_forever' => 'જ્યાં સુધી ડિલિવરી રેકોર્ડ ટકે ત્યાં સુધી',
        'ret_help' => 'ડિલિવરી લોગ મોકલાયેલો ચોક્કસ payload સંગ્રહે છે. <strong>Full record</strong> ફોર્મેટ સાથે તે <strong>આખી ટિકિટ</strong> હોય છે &mdash; વિષય, વિનંતીકર્તા, બધું જ &mdash; અહીં સાદા ટેક્સ્ટમાં કૉપિ થયેલું. આટલા દિવસ પછી payload અને response ની બોડી ભૂંસાઈ જાય છે, જ્યારે ડિલિવરી <em>રેકોર્ડ</em> (endpoint, સ્થિતિ, સમય, ભૂલો) ઓડિટ માટે ત્યાં સુધી રહે છે જ્યાં સુધી ઉપરની લોગ જાળવણી ({days} દિવસ) આખી પંક્તિ દૂર ન કરે.',
