    'bingo' => [
        'heading' => 'Feature Bingo',
        'intro' => 'મોટાભાગના લોકો તેમની પાસે જે છે તેનો થોડો ભાગ જ વાપરે છે. દરેક કાર્ડ FreeITSM જે કરી શકે તેવી એક બાબત છે, અને અહીં સેટ થતાં જ તેનો સ્ટાર પ્રકાશિત થાય છે. તે શું છે, શા માટે કરવા જેવું છે અને ક્યાં સેટ કરવું તે જોવા એક ખોલો. જે તમે ક્યારેય વાપરવાના નથી તેને આપણા માટે નથી તરીકે ચિહ્નિત કરો અને તે સ્કોરમાંથી નીકળી જશે.',
