        'conf_heading' => 'ગોપનીય ટિકિટ',
        'conf_desc' => 'ગોપનીય તરીકે ચિહ્નિત ટિકિટનું શું મેનેજરને દેખાય - HR ને મોકલેલ નિદાન, અથવા મેનેજર વિશે જ ફરિયાદ.',
        'conf_none' => 'બિલકુલ કંઈ નહીં (ભલામણ કરેલ)',
        'conf_none_desc' => 'ટિકિટને સંપૂર્ણપણે બાકાત રાખવામાં આવે છે. મેનેજર એ પણ જાણી શકતા નથી કે તે અસ્તિત્વમાં છે.',
        'conf_stub' => 'કે ગોપનીય ટિકિટ અસ્તિત્વમાં છે',
        'conf_stub_desc' => '"Confidential ticket" તરીકે તેના નંબર અને સ્થિતિ સાથે દર્શાવાય છે, તેમાં શું લખ્યું છે તે નહીં. ધ્યાન રાખો કે આટલાથી પણ મેનેજરને ખબર પડી શકે છે કે કોઈએ કંઈક ખાનગી નોંધાવ્યું છે.',
        'conf_all' => 'બધું',
