        'notify_none' => 'જાણ ન કરો (ડિફોલ્ટ)',
        'notify_none_desc' => 'મેનેજર Team tickets જુએ ત્યારે નવી ટિકિટ જુએ છે.',
        'notify_email' => 'તેમને ઈમેઇલ કરો',
        'notify_email_desc' => 'ટિકિટના નંબર અને વિષય અને તેની લિંક સાથેનો ઈમેઇલ, ટિકિટ મેઇલબોક્સમાંથી મેનેજરના સરનામે મોકલવામાં આવે છે. સરનામું ન હોય તેવા મેનેજરને કશું મળતું નથી. લિંક માટે જાહેર વેબ સરનામું જોઈએ (Tickets → Settings → Email Templates) - તે વિના, ઈમેઇલથી આવતી ટિકિટ ચાલે નહીં તેવી લિંક મોકલે છે.',
