        'logo_position_desc' => 'બારમાં તે પોર્ટલના નામની બાજુમાં, નાનો અને હંમેશા સ્ક્રીન પર રહે છે. પેજ પર તે ટોચ પર એક વાર, મોટો, પેજની બેકગ્રાઉન્ડ પર દેખાય છે &mdash; અને ત્યારે બાર પોર્ટલનું નામ પુનરાવર્તિત કરવાને બદલે ફક્ત તે એકલું બતાવે છે.',
