        'self_close_label' => 'લોકોને પોતાની ટિકિટ બંધ કરવા દો',
        'self_close_desc' => 'પોર્ટલમાં ટિકિટ પર <strong>હવે જરૂર નથી</strong> બટન ઉમેરે છે. ટિકિટ એવી નોંધ સાથે બંધ થાય છે કે વિનંતી કરનારે તેને બંધ કરી, જેથી ટ્રેઇલમાં કોણે કર્યું તે દેખાય અને એવું ન લાગે કે વિશ્લેષકે એવું કંઈક ઉકેલ્યું જેને તેમણે અડક્યું પણ નથી. જેના પર કોઈ પહેલેથી કામ કરી રહ્યું છે તેવી ટિકિટ તેઓ બંધ કરી શકતા નથી, સિવાય કે તે તેમની પુષ્ટિની રાહમાં ઉકેલાયેલી હોય &mdash; તે તો પુષ્ટિ કરવાનું કામ પહેલેથી જ તેમનું છે.',
